import React, { useEffect, useState } from 'react';
import api from '../api';

export default function AdminDashboard() {
  const [stats, setStats] = useState({ books: 0, users: 0, orders: 0 });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadStats() {
      try {
        const res = await api.get('/api/admin/stats');
        setStats(res.data);
      } catch (err) {
        alert(err?.response?.data?.message || err.message);
      } finally {
        setLoading(false);
      }
    }
    loadStats();
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-screen text-white text-2xl font-semibold">
        Loading Dashboard...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-r from-indigo-700 via-purple-700 to-pink-600 bg-[length:200%_200%] animate-gradientMove text-white p-10 transition-all duration-700">
      <div className="max-w-6xl mx-auto">
        <h1 className="text-5xl font-extrabold text-center mb-10 drop-shadow-lg">📊 Admin Dashboard</h1>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-8">
          <div className="bg-white/10 backdrop-blur-md p-8 rounded-2xl shadow-2xl hover:scale-105 hover:bg-white/20 transition-transform duration-300">
            <h2 className="text-2xl font-bold mb-2">📚 Total Books</h2>
            <p className="text-4xl font-extrabold">{stats.books}</p>
          </div>

          <div className="bg-white/10 backdrop-blur-md p-8 rounded-2xl shadow-2xl hover:scale-105 hover:bg-white/20 transition-transform duration-300">
            <h2 className="text-2xl font-bold mb-2">👥 Users</h2>
            <p className="text-4xl font-extrabold">{stats.users}</p>
          </div>

          <div className="bg-white/10 backdrop-blur-md p-8 rounded-2xl shadow-2xl hover:scale-105 hover:bg-white/20 transition-transform duration-300">
            <h2 className="text-2xl font-bold mb-2">🛒 Orders</h2>
            <p className="text-4xl font-extrabold">{stats.orders}</p>
          </div>
        </div>

        {/* Admin Options Section */}
        <div className="mt-16 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
          {[
            { name: 'Manage Books', path: '/admin/books', icon: '📘' },
            { name: 'Manage Users', path: '/admin/users', icon: '🧑‍💻' },
            { name: 'View Orders', path: '/admin/orders', icon: '📦' },
            { name: 'Add New Book', path: '/admin/add-book', icon: '➕' },
            { name: 'Feedbacks', path: '/admin/feedback', icon: '💬' },
            { name: 'Settings', path: '/admin/settings', icon: '⚙️' },
          ].map((item, index) => (
            <a
              key={index}
              href={item.path}
              className="bg-white/10 backdrop-blur-md p-8 rounded-2xl shadow-2xl flex flex-col items-center justify-center hover:scale-105 hover:bg-white/20 transition-transform duration-300 text-center"
            >
              <span className="text-5xl mb-4">{item.icon}</span>
              <h3 className="text-2xl font-semibold">{item.name}</h3>
            </a>
          ))}
        </div>
      </div>
    </div>
  );
}
